'use client';
import {useEffect,useState} from 'react';
import {api,send} from '@/lib/client';
import type {Page} from '@/lib/types';
import {recordBalanceAdjustment} from '@/lib/customer-commerce';
import {useData,usePanel} from './context';
import {OrderTopNav} from '@/reference-ui/features/orders/components/OrderTopNav';
import {OrderFilterDropdown,type FilterState} from '@/reference-ui/features/orders/components/OrderFilterDropdown';
import {OrderListCard} from '@/reference-ui/features/orders/order-list/components/OrderListCard';
import {RechargeListCard} from '@/reference-ui/features/orders/recharge-list/components/RechargeListCard';
import {ReviewPaymentModal} from '@/reference-ui/features/orders/components/ReviewPaymentModal';
import {financeQuery,orderItem,rechargeItem,businessTime,type OrderRow,type RechargeRow} from '@/reference-ui/shared/services/financePanelApi';
import {getQuickDisplayDateRange,toIsoDate} from '@/reference-ui/shared/utils/dateRange';
import {formatCurrency} from '@/reference-ui/shared/utils/currency';
import type {CanonicalOrder,CanonicalRechargeOrder} from '@/reference-ui/features/orders/types/order.types';
import {useNavigate} from '@/reference-ui/shared/hooks/financeNavigation';
import {usersApi,type UserDetail} from '@/reference-ui/shared/services/usersApi';
import {UserStatusConfirmModal} from '@/reference-ui/features/users/components/UserStatusConfirmModal';
const width='w-full max-w-[560px] md:max-w-[760px] lg:max-w-[900px] xl:max-w-[1000px] 2xl:max-w-[1180px]';
const glass='border border-white/10 bg-black/40 rounded-lg backdrop-blur-md shadow-lg';
export function FinanceCheck({mode}:{mode:'orders'|'recharge'}){
 const {profile,cache,invalidate,notify}=usePanel();const recharge=mode==='recharge';const navigate=useNavigate();
 const [statusUser,setStatusUser]=useState<UserDetail|null>(null);
 const [page,setPage]=useState(0),[size,setSize]=useState(10),[query,setQuery]=useState(''),[search,setSearch]=useState(''),[showSearch,setShowSearch]=useState(false),[showFilter,setShowFilter]=useState(false),[filters,setFilters]=useState<FilterState>({status:'all',startDate:'',endDate:''}),[error,setError]=useState(''),[selected,setSelected]=useState<RechargeRow|null>(null),[dialogMode,setDialogMode]=useState<'view'|'review'|'adjust'>('view'),[busy,setBusy]=useState(false),[,tick]=useState(0);
 useEffect(()=>{const t=setTimeout(()=>{setSearch(query);setPage(0);},350);return()=>clearTimeout(t);},[query]);
 useEffect(()=>{const t=setInterval(()=>tick(v=>v+1),1000);return()=>clearInterval(t);},[]);
 const params=financeQuery({size,cursor:`page:${page}`,search,status:filters.status,startDate:filters.quickRange?toIsoDate(filters.startDate):undefined,endDate:filters.quickRange?toIsoDate(filters.endDate):undefined},recharge).toString();
 const result=useData(`finance-check:${mode}:${params}`,()=>api<Page<OrderRow|RechargeRow>>(`${recharge?'recharges':'customer-orders'}?${params}`));
 const summary=useData('customer-wallet:summary',()=>api<{walletBalance:number}>('customer-wallet/summary'));
 const settings=useData('payment-settings',()=>api<{paymentsEnabled:boolean}>('payment-settings'));
 const rows=result.data?.content||[];
 const openRecharge=async(row:CanonicalRechargeOrder,requested:'view'|'review'|'adjust')=>{if(busy)return;setBusy(true);setError('');try{const r=await api<RechargeRow>('recharges/'+row.id);if(requested==='review'&&r.status!=='PENDING')throw Error('This payment has already been reviewed. Refresh the list.');if(requested==='adjust'&&r.status!=='APPROVED')throw Error('Only completed recharges can be adjusted.');setSelected(r);setDialogMode(requested);}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
 const openInfo=(row:CanonicalOrder|CanonicalRechargeOrder)=>{const record=rows.find(r=>String(r.id)===row.id);if(record){cache.seed(`finance-detail:${profile.shop.id}:${mode}:${row.id}`,record);void cache.load(`finance-detail-user:${profile.shop.id}:${record.customerId}`,()=>usersApi.detail(String(record.customerId)));}navigate(`${recharge?'/recharge-list/topup-':'/order-list/ord-'}${row.id}`);};
 const openBan=async(row:CanonicalOrder|CanonicalRechargeOrder)=>{if(busy)return;const record=rows.find(r=>String(r.id)===row.id);if(!record)return;setBusy(true);setError('');try{setStatusUser(await usersApi.detail(String(record.customerId)));}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
 const changeReview=async(id:string,action:'APPROVE'|'REJECT',amount?:string)=>{const n=Number(amount);if(action==='APPROVE'&&(!Number.isInteger(n)||n<50||n>1000000||n%50!==0))throw Error('Enter 50 to 1,000,000 MMK in multiples of 50.');await send(`recharges/${id}/review`,{action,amount:action==='APPROVE'?n:null,note:action==='REJECT'?'Payment could not be verified':'Payment verified'});invalidate();notify(action==='APPROVE'?'Recharge approved. Customer wallet credited.':'Recharge rejected.');};
 return <><main className="reference-finance-ui finance-check-page"><div className="w-full space-y-3 sm:space-y-4 flex-1 flex flex-col items-center">
 <div className="w-full flex flex-col items-center gap-2 sm:gap-2.5"><div className={`${width} ${glass} h-12 flex items-center justify-center text-xs font-bold`} aria-label="Total customer wallet balance">{summary.data?formatCurrency(summary.data.walletBalance):summary.error?'Balance unavailable':'Loading balance…'}</div><OrderTopNav active={mode} onActiveRefresh={invalidate}/></div>
 <div className={`${width} ${glass} p-3.5 sm:p-4 relative z-20`}>
 <div className="grid grid-cols-4 gap-2 mb-3 w-full">{['Today','Search','Filter'].map(label=><button type="button" key={label} className="w-full border border-white/10 px-2 py-1.5 rounded-lg font-bold text-xs sm:text-sm text-white/70 bg-white/5 hover:bg-white/10" onClick={()=>{if(label==='Today'){setFilters(s=>({...s,...getQuickDisplayDateRange('Today'),quickRange:'Today'}));setPage(0);}else if(label==='Search'){setShowSearch(v=>!v);setShowFilter(false);}else{setShowFilter(v=>!v);setShowSearch(false);}}}>{label}</button>)}
 {recharge?<button type="button" disabled={busy||!settings.data} aria-pressed={settings.data?.paymentsEnabled||false} className="w-full border border-white/10 bg-white/5 px-1.5 py-1.5 rounded-lg font-bold text-xs" onClick={async()=>{setBusy(true);setError('');try{await send('payment-settings',{paymentsEnabled:!settings.data?.paymentsEnabled},'PUT');invalidate();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}><span className={settings.data?.paymentsEnabled?'text-emerald-400':'text-white/50'}>{busy?'Saving…':settings.data?.paymentsEnabled?'Online':'Offline'}</span></button>:<button type="button" className="w-full border border-white/10 rounded-lg bg-white/5 text-xs text-white/70" onClick={invalidate}>Refresh</button>}</div>
 <div className="flex items-center justify-between py-1 px-0.5 text-xs sm:text-sm"><span className="text-white/40">Loaded: <b className="text-white/90">{rows.length}</b></span><div className="flex items-center gap-3"><select aria-label="Rows per page" value={size} onChange={e=>{setSize(Number(e.target.value));setPage(0);}} className="glass-effect-btn text-xs h-7 px-2">{[10,50,100].map(n=><option key={n} value={n}>{n}</option>)}</select><div className="glass-effect-btn h-7 flex items-center gap-4 px-2"><button aria-label="Previous page" disabled={!page} onClick={()=>setPage(v=>v-1)}>‹</button><span>{page+1}</span><button aria-label="Next page" disabled={!result.data||result.data.last} onClick={()=>setPage(v=>v+1)}>›</button></div></div></div>
 {showSearch&&<input autoFocus aria-label="Search orders" maxLength={100} className="mt-3 w-full h-[38px] rounded-lg border border-white/10 bg-black/40 px-3 text-sm text-white" placeholder="Search Order ID, Buyer..." value={query} onChange={e=>setQuery(e.target.value)}/>}
 <OrderFilterDropdown isOpen={showFilter} onClose={()=>setShowFilter(false)} onApply={f=>{setFilters(f);setPage(0);}} initialFilters={filters} title={recharge?'Recharge Filter':'Orders Filter'} statusOptions={[{label:'All',value:'all'},{label:'Completed',value:'completed'},{label:'Processing',value:'processing'},{label:recharge?'Rejected':'Failed',value:recharge?'cancelled':'failed'}]} includeAllTime/>
 </div>
 {(error||result.error||result.refreshError||summary.error||settings.error)&&<div className={width} role="alert"><p className="border border-red-500/30 rounded-lg p-3 text-sm text-red-300">{error||result.error||result.refreshError||summary.error||settings.error}<button className="ml-3 underline" onClick={invalidate}>Try again</button></p></div>}
 <div className={`${width} space-y-3 sm:space-y-4`} aria-busy={result.loading}>{!result.data?<p className="p-6 text-center text-white/50">Loading…</p>:!rows.length?<p className={`${glass} p-10 text-center text-white/40`}>No orders found</p>:rows.map(row=>recharge?<RechargeListCard key={row.id} order={rechargeItem(row as RechargeRow)} onViewPayment={r=>void openRecharge(r,'view')} onModify={r=>void openRecharge(r,r.isConfirmed?'adjust':'review')} onInfo={r=>void openInfo(r)} onBan={r=>void openBan(r)}/>:<OrderListCard key={row.id} order={{...orderItem(row as OrderRow),uid:(row as OrderRow).playerId||'',price:Number((row as OrderRow).sellPrice)}} onInfo={r=>void openInfo(r)} onBan={r=>void openBan(r)} onCopyInfo={async r=>{try{await navigator.clipboard.writeText([r.publicOrderId,r.product,r.uid,r.serverId,r.packageName,`Qty: ${r.quantity}`].filter(Boolean).join('\n'));notify('Order information copied.');}catch{setError('Unable to copy. Open order information to view the details.');}}} onManualStatusChange={async(r,status)=>{try{await send(`customer-orders/${r.id}/settle`,{action:status==='Completed'?'SUCCESS':'REFUND'});invalidate();notify('Order updated.');}catch(e){setError((e as Error).message);}}}/>)}</div>
 </div>
 <ReviewPaymentModal isOpen={!!selected} onClose={()=>setSelected(null)} order={selected?rechargeItem(selected):null} mode={dialogMode} onConfirm={(id,amount)=>changeReview(id,'APPROVE',amount)} onCancelOrder={id=>changeReview(id,'REJECT')} onAdjustBalance={async(_id,amount,reason,type)=>{if(!selected||!reason.trim())throw Error('Enter an adjustment reason.');await recordBalanceAdjustment(profile.shop.code,profile.id,selected.customerId,{amount:(type==='debit'?-1:1)*Number(amount),note:`${selected.publicTransactionId}: ${reason.trim()}`});invalidate();notify('Customer wallet adjusted.');}}/>
 <UserStatusConfirmModal isOpen={!!statusUser} onClose={()=>setStatusUser(null)} user={statusUser} action={statusUser?.status==='Banned'?'Unban':'Ban'} onConfirm={async user=>{await usersApi.setBanned(user.id,user.status!=='Banned');invalidate();notify(user.status==='Banned'?'User unbanned.':'User banned.');}}/>
 </main>
 </>;
}
